"""Test 9, job 2 (and job 3): the per-qubit analysis t9-rule.md fixes, from the job's raw counts, by scan_t9.py
(unchanged). Written before any job's counts existed (17 October 2026, in the dry run).

Per qubit of the job's set (its classical bit is its rank in the set sorted by ascending index, read with bit 0
rightmost as test 8 reads it):
  - each repeat's 16 positions by their labels (repeat, circuit, requested wait); P(1) per wait per quadrature; t is
    each position's scheduled wait from its label (equal in X and Y, checked);
  - tau held: job 1's fitted S decay for the qubit (fits-t9-job1.json, the S fit's tau_us), clipped to 10 to 400 us
    by scan_t9; for job 3, 60 us. The value used is recorded for every qubit;
  - scan_t9.analyse_qubit: the eighteen fits and s_k, the three models, the verdict, the flag ONE-LINE FIT POOR,
    usable (e from job 0 at or below 0.03 and the median fitted A at least 0.2); bootstrap seeds SeedSequence([9307,
    qubit, k]) (job 3: [9308, qubit, k]);
  - the readout circuits at the start and at the end of the job: P(1|0), P(0|1) and e, each block apart.
A STEPPED qubit's change is placed at the first position of the repeat that starts its new level, as a fraction of the
job's 292 positions; the job's recorded machine time is set beside it by the report. Parallel: one task per qubit.

Usage: python -B analyse2_t9.py --counts results-t9-job2-counts.json --survey survey-t9.json [--fits1 fits-t9-job1.json]
       [--job3] [--workers 9] [--out fits-t9-job2.json]"""
from __future__ import annotations

import os

for _v in ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS", "VECLIB_MAXIMUM_THREADS"):
    os.environ.setdefault(_v, "1")
import sys  # noqa: E402

sys.dont_write_bytecode = True
import argparse  # noqa: E402
import hashlib  # noqa: E402
import json  # noqa: E402
import time  # noqa: E402
from concurrent.futures import ProcessPoolExecutor  # noqa: E402
from pathlib import Path  # noqa: E402

import numpy as np  # noqa: E402

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import scan_t9 as S  # noqa: E402

RULE_SHA = "4858f55e37fbc72b1806ee4033028e30a59c1782009600f4d9d6fa71806181d4"


def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()


def read_scan(path):
    rec = json.loads(Path(path).read_text())
    labels, counts, shots = rec["labels"], rec["counts"], rec["shots"]
    qs = sorted(int(q) for q in rec["qubits"])
    n = len(qs)
    if len(labels) != S.N_REP * 16 + 4 or len(counts) != len(labels):
        sys.exit("STOP: not 292 positions")
    if [l.get("position") for l in labels] != list(range(len(labels))):
        sys.exit("STOP: the labels are not in position order")
    if set(shots) != {1000}:
        sys.exit("STOP: not 1,000 shots at every position")
    ones_pos = np.zeros((len(labels), n), np.int64)
    for k, cts in enumerate(counts):
        tot = 0
        for key, m in cts.items():
            b = np.frombuffer(key.replace(" ", "")[::-1].encode(), dtype=np.uint8).astype(np.int64) - 48
            if len(b) != n:
                sys.exit(f"STOP: position {k} has a key of {len(b)} bits, not {n}")
            ones_pos[k] += b * m
            tot += m
        if tot != shots[k]:
            sys.exit(f"STOP: position {k} returned {tot} shots")
    wi = {t: i for i, t in enumerate(S.WAITS2_US)}
    idx = np.full((S.N_REP, 2, 8), -1)
    tw = {}
    for k, lab in enumerate(labels):
        if lab["circuit"] in ("X", "Y"):
            idx[lab["repeat"] - 1, "XY".index(lab["circuit"]), wi[lab["t_requested_us"]]] = k
            tw.setdefault((lab["circuit"], lab["t_requested_us"]), set()).add(float(lab["scheduled_wait_us"]))
    if (idx < 0).any():
        sys.exit("STOP: a repeat's position is missing")
    waits = []
    for t in S.WAITS2_US:
        x, y = tw[("X", t)], tw[("Y", t)]
        if len(x) != 1 or x != y:
            sys.exit("STOP: a wait is not the same in every repeat and in both quadratures")
        waits.append(next(iter(x)))
    ro = {(lab["block"], lab["circuit"]): k for k, lab in enumerate(labels) if lab["circuit"] in ("P10", "P01")}
    return rec, qs, ones_pos, idx, waits, ro


def one(task):
    q, j, ones_rep, waits, tau, root, e0, ro_ones, n = task
    t0 = time.time()
    out = S.analyse_qubit(ones_rep, n, waits, tau, lambda k: [root, q, k], e_job0=e0,
                          first_positions=[2 + 16 * (r - 1) for r in range(1, S.N_REP + 1)], n_positions=S.N_REP * 16 + 4)
    ro = {}
    for block in ("start", "end"):
        p10 = ro_ones[(block, "P10")] / n
        p01 = 1 - ro_ones[(block, "P01")] / n
        ro[block] = {"P1_given_0": p10, "P0_given_1": p01, "e": (p10 + p01) / 2}
    out.update({"qubit": q, "clbit": j, "readout": ro, "waits_us": waits, "elapsed_s": round(time.time() - t0, 2)})
    return out

