  - the pair readings are the rule's, named after the data and not verdicts.
Usage: python -B tables_t9.py --fits1 F1 --fits2 F2 [--fits3 F3] --survey SV --sets SETS --t8 DIR [--out beside-t9.json]"""
import argparse
import json
from pathlib import Path

import numpy as np
from scipy.stats import chi2

SIG_RAMSEY, SIG_READOUT = 512.0, float(chi2.ppf(0.999, 2))
PAIR_READINGS = {("TWO FIXED FREQUENCIES", "STEPPED", None): "134's kind of record in test 8 (two lines at different times)",
                 ("TWO FIXED FREQUENCIES", "STEADY", True): "143's kind (two lines at once)",
                 ("TWO FIXED FREQUENCIES", "STEADY", False): "a split below the scan's resolution",
                 ("NO RESOLVED SPLIT", "MOVING", None): "one line moving", ("NO RESOLVED SPLIT", "STEPPED", None): "one line moving"}


def reading(v1, v2, flag):
