        lines.append(f"| {q} | {word} | {d['held_out_error_S']:.4f} | {d['held_out_error_P']:.4f} | {P['delta_MHz']*1e3:.2f} ({d['delta_ci90_kHz'][0]:.2f} to {d['delta_ci90_kHz'][1]:.2f}) | "
                     f"{P['b']:.3f} ({d['b_ci90'][0]:.3f} to {d['b_ci90'][1]:.3f}) | {P['Delta0_MHz']*1e3:.1f} | {P['tau_prime_us']:.1f} | {S_['Delta_MHz']*1e3:.1f}, {S_['tau_us']:.1f} | "
